/**
 * Aggregates every MMFF94 parameter table into one importable module.
 *
 * Each table is generated by the extraction script
 * (scripts/extract-mmff94-par.py) from OpenBabel's .par files. The
 * class-resolution helpers (parameter-classes.ts) and the empirical
 * rules (torsion-empirical.ts) are hand-written and sit beside the
 * tables because they answer the same question: WHICH parameters
 * apply to this bond/angle/torsion.
 *
 * Keys include a leading class column (e.g., "0-1-1", "1-2-2");
 * lookup_param() provides the class-0 fallback, and the class system
 * in parameter-classes.ts selects the class itself.
 */

export { lookup_param } from './lookup';
export { ATOM_TYPES } from './atom-types';
export { ATOM_TYPE_PROPERTIES, type AtomTypeProperties } from './atom-type-properties';
export { BOND_PARAMS } from './bond';
export { ANGLE_PARAMS, type AngleParams } from './angle';
export { STRETCH_BEND_PARAMS, type StretchBendParams } from './stretch-bend';
export { TORSION_PARAMS } from './torsion';
export type { TorsionParams } from './torsion';
export { VDW_PARAMS } from './van-der-waals';
export { BCI_PARAMS, BCI_DEFAULT_PARAMS } from './bci';
export { OOP_PARAMS } from './out-of-plane';
export { DEFAULT_STRETCH_BEND } from './default-stretch-bend';
export {
  make_class_context,
  get_bond_order,
  is_aromatic_bond,
  ELEMENT_ROW,
  bond_type_flag,
  angle_class,
  torsion_class,
  strbnd_type,
  bond_parameters,
  angle_parameters,
  lookup_torsion,
  type ClassContext,
} from './parameter-classes';
export { empirical_torsion } from './torsion-empirical';
